import { prisma } from '@/lib/prisma';

interface FetchPostsParams {
  limit?: number;
  cursor?: string; // ID of the last item from previous fetch
}

export async function getPaginatedPosts({ limit = 10, cursor }: FetchPostsParams) {
  const posts = await prisma.post.findMany({
    take: limit + 1, // Fetch 1 extra item to determine if hasNextPage is true
    skip: cursor ? 1 : 0, // Skip the cursor itself
    cursor: cursor ? { id: cursor } : undefined,
    orderBy: { id: 'desc' }, // Must order by unique cursor field
  });

  let nextCursor: string | undefined = undefined;
  if (posts.length > limit) {
    const nextItem = posts.pop(); // Remove the extra probe item
    nextCursor = nextItem?.id;
  }

  return {
    items: posts,
    nextCursor,
    hasNextPage: Boolean(nextCursor)
  };
}
